// ============================================================================
// devbench-cpp-parser — High-Performance Zero-Copy JSON Parser & Serializer
// SDLC Phase: software_design
// ----------------------------------------------------------------------------
// Design goals:
//   * Zero-copy parsing: string_view slices reference the input buffer directly
//     whenever unescaping is not required.
//   * Memory pooling: a bump-pointer arena (MemoryPool) owns all AST nodes,
//     dynamic arrays, and unescaped strings in a single-pass parse.
//   * Cache-friendly layout: arrays/objects stored as contiguous slices of
//     JsonValue; arena chunks keep allocations local.
//   * Strict RFC 8259 compliance with precise error reporting.
// ============================================================================
#pragma once

#include <cstddef>
#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

namespace json {

// ============================================================================
// 1. Memory Pool / Arena
// ============================================================================
// Bump-pointer allocator. Allocates from fixed-size blocks (default 64 KiB).
// - O(1) allocation (pointer bump + alignment fix-up).
// - O(1) bulk reset: all memory is reclaimed by rewinding the cursor.
// - Not thread-safe by design; each parse owns its arena.
class MemoryPool {
public:
    static constexpr std::size_t kDefaultBlockSize = 64 * 1024;

    explicit MemoryPool(std::size_t block_size = kDefaultBlockSize);
    ~MemoryPool();

    MemoryPool(const MemoryPool&) = delete;
    MemoryPool& operator=(const MemoryPool&) = delete;

    // Allocate `size` bytes aligned to `alignment` (power of two).
    void* allocate(std::size_t size, std::size_t alignment = alignof(std::max_align_t));

    // Allocate and copy a byte range (used for unescaped strings).
    std::string_view allocate_copy(const char* data, std::size_t size);

    // Reclaim all memory (keeps blocks for reuse).
    void reset();

    std::size_t total_allocated() const noexcept { return total_allocated_; }
    std::size_t block_count() const noexcept { return blocks_.size(); }

private:
    struct Block {
        char* data;
        std::size_t size;
        std::size_t offset;   // next free byte
    };

    Block& current_block();
    void add_block(std::size_t min_size);

    std::vector<Block> blocks_;
    std::size_t block_size_;
    std::size_t total_allocated_ = 0;
};

// ============================================================================
// 2. JSON Value Representation
// ============================================================================
enum class JsonType : uint8_t {
    Null,
    Bool,
    Int,
    Double,
    String,   // string_view (zero-copy or arena-owned)
    Array,    // slice into arena
    Object,   // slice into arena
};

struct JsonValue {
    JsonType type = JsonType::Null;

    union {
        bool        boolean;
        int64_t     integer;
        double      number;
        std::string_view string;   // zero-copy view into input or arena
        struct { const JsonValue* data; std::size_t size; } array;
        struct { const JsonValue* data; std::size_t size; } object; // key/value pairs
    } as;

    // --- Accessors ----------------------------------------------------------
    bool is_null()   const noexcept { return type == JsonType::Null; }
    bool is_bool()   const noexcept { return type == JsonType::Bool; }
    bool is_int()    const noexcept { return type == JsonType::Int; }
    bool is_double() const noexcept { return type == JsonType::Double; }
    bool is_number() const noexcept { return type == JsonType::Int || type == JsonType::Double; }
    bool is_string() const noexcept { return type == JsonType::String; }
    bool is_array()  const noexcept { return type == JsonType::Array; }
    bool is_object() const noexcept { return type == JsonType::Object; }

    bool as_bool()   const noexcept { return as.boolean; }
    int64_t as_int() const noexcept { return as.integer; }
    double as_double() const noexcept { return type == JsonType::Int ? static_cast<double>(as.integer) : as.number; }
    std::string_view as_string() const noexcept { return as.string; }

    const JsonValue* begin() const noexcept { return as.array.data; }
    const JsonValue* end()   const noexcept { return as.array.data + as.array.size; }
    std::size_t size()       const noexcept { return as.array.size; }

    // Object iteration: entries are stored as [key, value] pairs.
    const JsonValue* find(std::string_view key) const noexcept;
};

// ============================================================================
// 3. Error Reporting
// ============================================================================
enum class JsonErrorCode : uint8_t {
    None = 0,
    UnexpectedToken,
    InvalidValue,
    UnterminatedString,
    InvalidEscape,
    InvalidNumber,
    InvalidUnicode,
    TrailingComma,
    MissingComma,
    MissingColon,
    MissingKey,
    DuplicateKey,
    UnexpectedEnd,
    DepthExceeded,
    InvalidUtf8,
};

struct JsonError {
    JsonErrorCode code = JsonErrorCode::None;
    std::size_t   offset = 0;   // byte offset into input
    std::size_t   line = 1;     // 1-based line
    std::size_t   column = 1;   // 1-based column
    std::string   message;      // human-readable detail

    explicit operator bool() const noexcept { return code != JsonErrorCode::None; }
};

// ============================================================================
// 4. Parser
// ============================================================================
struct ParseOptions {
    std::size_t max_depth = 512;      // nesting depth guard
    bool allow_trailing_comma = false; // strict RFC 8259 by default
    bool allow_duplicate_keys = false; // strict RFC 8259 by default
};

struct ParseResult {
    JsonValue root;      // valid only when error.code == None
    JsonError error;
    std::size_t consumed = 0;  // bytes consumed from input
};

class JsonParser {
public:
    // Parse a JSON document from a contiguous buffer. The input buffer must
    // outlive the returned JsonValue (zero-copy string views reference it).
    ParseResult parse(std::string_view input, const ParseOptions& options = {});

    // Convenience overload for std::string inputs.
    ParseResult parse(const std::string& input, const ParseOptions& options = {});

private:
    // Recursive-descent scanner state.
    struct Cursor {
        const char* p;
        const char* end;
        std::size_t line = 1;
        std::size_t column = 1;
        std::size_t depth = 0;
    };

    ParseResult parse_value(Cursor& cur, MemoryPool& pool, const ParseOptions& opts);
    ParseResult parse_array(Cursor& cur, MemoryPool& pool, const ParseOptions& opts);
    ParseResult parse_object(Cursor& cur, MemoryPool& pool, const ParseOptions& opts);
    ParseResult parse_string(Cursor& cur, MemoryPool& pool, const ParseOptions& opts);
    ParseResult parse_number(Cursor& cur, const ParseOptions& opts);
    ParseResult parse_literal(Cursor& cur, const char* lit, JsonType type);

    void skip_whitespace(Cursor& cur) noexcept;
    JsonError make_error(Cursor& cur, JsonErrorCode code, std::string message) const noexcept;
};

// ============================================================================
// 5. Serializer
// ============================================================================
struct SerializeOptions {
    int indent = -1;              // -1 = compact, >=0 = pretty with N spaces
    bool escape_unicode = false;  // emit \uXXXX for non-ASCII
    bool sort_keys = false;       // deterministic output (object keys sorted)
};

class JsonSerializer {
public:
    // Serialize a JsonValue tree into `out`. Returns false on structural error.
    bool serialize(const JsonValue& value, std::string& out,
                   const SerializeOptions& options = {}) const;

    std::string serialize(const JsonValue& value, const SerializeOptions& options = {}) const;

private:
    void write_value(const JsonValue& value, std::string& out,
                     const SerializeOptions& opts, int depth) const;
    void write_string(std::string_view s, std::string& out,
                      const SerializeOptions& opts) const;
    void write_indent(std::string& out, int depth, const SerializeOptions& opts) const;
};

// ============================================================================
// 6. Free Functions
// ============================================================================
// One-shot convenience API.
ParseResult parse_json(std::string_view input, const ParseOptions& options = {});
std::string serialize_json(const JsonValue& value, const SerializeOptions& options = {});

} // namespace json
