package com.app.service;

import com.app.dto.AuthResponse;
import com.app.dto.LoginRequest;
import com.app.dto.RegisterRequest;
import com.app.model.User;
import com.app.repository.UserRepository;
import com.app.security.JwtTokenProvider;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.BadCredentialsException;
import org.springframework.security.authentication.DisabledException;
import org.springframework.security.authentication.LockedException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.crypto.password.PasswordEncoder;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
@DisplayName("AuthService Unit Tests")
public class AuthServiceTest {

    @Mock
    private UserRepository userRepository;

    @Mock
    private PasswordEncoder passwordEncoder;

    @Mock
    private JwtTokenProvider tokenProvider;

    @Mock
    private AuthenticationManager authenticationManager;

    @Mock
    private Authentication authentication;

    @InjectMocks
    private AuthService authService;

    private RegisterRequest registerRequest;
    private LoginRequest loginRequest;
    private User testUser;

    @BeforeEach
    void setUp() {
        registerRequest = new RegisterRequest();
        registerRequest.setUsername("testuser");
        registerRequest.setEmail("test@example.com");
        registerRequest.setPassword("Password123!");

        loginRequest = new LoginRequest();
        loginRequest.setUsername("testuser");
        loginRequest.setPassword("Password123!");

        testUser = new User();
        testUser.setId(1L);
        testUser.setUsername("testuser");
        testUser.setEmail("test@example.com");
        testUser.setPassword("encodedPassword123");
    }

    @Nested
    @DisplayName("User Registration Tests")
    class RegistrationTests {

        @Test
        @DisplayName("Should successfully register a new user and return AuthResponse")
        void register_Success() {
            when(userRepository.existsByUsername("testuser")).thenReturn(false);
            when(userRepository.existsByEmail("test@example.com")).thenReturn(false);
            when(passwordEncoder.encode("Password123!")).thenReturn("encodedPassword123");
            when(userRepository.save(any(User.class))).thenReturn(testUser);
            when(tokenProvider.generateToken(any(Authentication.class))).thenReturn("mocked.jwt.token");
            when(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class))).thenReturn(authentication);

            AuthResponse response = authService.register(registerRequest);

            assertNotNull(response);
            assertEquals("mocked.jwt.token", response.getAccessToken());
            assertEquals("Bearer", response.getTokenType());

            ArgumentCaptor<User> userCaptor = ArgumentCaptor.forClass(User.class);
            verify(userRepository).save(userCaptor.capture());
            User savedUser = userCaptor.getValue();
            assertEquals("testuser", savedUser.getUsername());
            assertEquals("test@example.com", savedUser.getEmail());
            assertEquals("encodedPassword123", savedUser.getPassword());
            verify(passwordEncoder).encode("Password123!");
        }

        @Test
        @DisplayName("Should throw exception when username is already taken")
        void register_DuplicateUsername_ThrowsException() {
            when(userRepository.existsByUsername("testuser")).thenReturn(true);

            assertThrows(IllegalArgumentException.class, () -> authService.register(registerRequest));
            verify(userRepository, never()).save(any(User.class));
            verify(passwordEncoder, never()).encode(anyString());
        }

        @Test
        @DisplayName("Should throw exception when email is already in use")
        void register_DuplicateEmail_ThrowsException() {
            when(userRepository.existsByUsername("testuser")).thenReturn(false);
            when(userRepository.existsByEmail("test@example.com")).thenReturn(true);

            assertThrows(IllegalArgumentException.class, () -> authService.register(registerRequest));
            verify(userRepository, never()).save(any(User.class));
            verify(passwordEncoder, never()).encode(anyString());
        }
    }

    @Nested
    @DisplayName("User Authentication / Login Tests")
    class LoginTests {

        @Test
        @DisplayName("Should successfully authenticate user and return JWT token")
        void login_Success() {
            when(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class)))
                    .thenReturn(authentication);
            when(tokenProvider.generateToken(authentication)).thenReturn("mocked.jwt.token");

            AuthResponse response = authService.login(loginRequest);

            assertNotNull(response);
            assertEquals("mocked.jwt.token", response.getAccessToken());
            assertEquals("Bearer", response.getTokenType());
            verify(authenticationManager).authenticate(any(UsernamePasswordAuthenticationToken.class));
            verify(tokenProvider).generateToken(authentication);
        }

        @Test
        @DisplayName("Should throw BadCredentialsException when credentials are invalid")
        void login_InvalidCredentials_ThrowsBadCredentialsException() {
            when(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class)))
                    .thenThrow(new BadCredentialsException("Invalid username or password"));

            assertThrows(BadCredentialsException.class, () -> authService.login(loginRequest));
            verify(tokenProvider, never()).generateToken(any());
        }

        @Test
        @DisplayName("Should throw DisabledException when user account is disabled")
        void login_DisabledAccount_ThrowsDisabledException() {
            when(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class)))
