        @DisplayName("Should throw LockedException when user account is locked")
        void login_LockedAccount_ThrowsLockedException() {
            when(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class)))
                    .thenThrow(new LockedException("Account locked"));

            assertThrows(LockedException.class, () -> authService.login(loginRequest));
            verify(tokenProvider, never()).generateToken(any());
